#!/usr/bin/env node
/*
 * Folds admin/web (index.html plus every local stylesheet and script it
 * references) into one self-contained HTML string, written out as a JS module
 * the native shell renders with `source={{ html }}`.
 *
 * Same approach as the pharmacy app's bundler, pointed at web/ — the admin
 * app is a separate project, so it carries its own copy rather than reaching
 * across into a sibling's scripts.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const WEB = path.join(ROOT, 'web');
const OUT = path.join(ROOT, 'src', 'webBundle.generated.js');

const read = (rel) => fs.readFileSync(path.join(WEB, rel), 'utf8');

/* A literal `</script>` inside inlined JS would close the host tag early. */
const escapeForScriptTag = (code) => code.replace(/<\/(script)/gi, '<\\/$1');

/* Replacement *functions*, never replacement strings: the inlined CSS and JS
   contain `$` sequences that String.replace would expand as match patterns. */
const insert = (haystack, needle, replacement) => haystack.replace(needle, () => replacement);

const STYLESHEET = /<link\s+rel="stylesheet"\s+href="([^"]+)"\s*\/?>/gi;
const SCRIPT = /<script\s+src="([^"]+)"\s*><\/script>/gi;

function inline() {
  let html = read('index.html');
  const inlined = [];

  const collect = (pattern) =>
    Array.from(html.matchAll(pattern)).map((m) => ({ tag: m[0], href: m[1] }));

  for (const { tag, href } of collect(STYLESHEET)) {
    if (/^(https?:)?\/\//.test(href) || href.startsWith('data:')) continue;
    const css = read(href);
    html = insert(html, tag, '<style>\n' + css + '\n</style>');
    inlined.push([href, css, false]);
  }

  for (const { tag, href } of collect(SCRIPT)) {
    if (/^(https?:)?\/\//.test(href) || href.startsWith('data:')) continue;
    const js = read(href);
    html = insert(html, tag, '<script>\n' + escapeForScriptTag(js) + '\n</script>');
    inlined.push([href, js, true]);
  }

  if (/<(?:link|script)[^>]+(?:href|src)="(?!data:|https?:|\/\/)/.test(html)) {
    throw new Error('index.html still references a local file after inlining');
  }

  /* Every source must survive byte for byte — cheap, and it is what catches
     silent mangling of the inlined payload. */
  for (const [name, source, isScript] of inlined) {
    const expected = isScript ? escapeForScriptTag(source) : source;
    if (!html.includes(expected)) {
      throw new Error('inlined content for ' + name + ' was altered during assembly');
    }
  }

  return { html, inlined };
}

const { html, inlined } = inline();
const banner = '/* GENERATED by scripts/bundle-web.js — do not edit. */\n' +
  '/* Sources: web/index.html, ' + inlined.map(([n]) => 'web/' + n).join(', ') + ' */\n';

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, banner + 'export default ' + JSON.stringify(html) + ';\n');

const kb = (Buffer.byteLength(html) / 1024).toFixed(1);
console.log('admin bundle-web: inlined ' + inlined.length + ' file(s) → src/webBundle.generated.js (' + kb + ' kB)');
